args.sparql:
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT ?album ?label ?dbpReleased ?dboReleaseDate WHERE {
  ?album rdfs:label ?label .
  FILTER(langMatches(lang(?label), "en"))
  FILTER regex(?label, "3\\.2\\.1", "i")
  OPTIONAL { ?album dbp:released ?dbpReleased }
  OPTIONAL { ?album dbo:releaseDate ?dboReleaseDate }
}

